contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: from address, caddress (target contract for transferFrom), tos array, value v
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);
        // observe c balance before
        uint balBefore = address(c).balance;
        bool reverted;
        // call and catch revert
        try c.transfer(from, caddress, _tos, v) returns (bool ok) {
            reverted = false;
            // if it returned, assert it returned true
            assert(ok == true);
            // and that c's balance did not increase (transfer should not move Ether from this contract)
            uint balAfter = address(c).balance;
            assert(balAfter == balBefore);
        } catch {
            reverted = true;
            // if reverted, ensure that nothing about c's balance changed (revert should revert state)
            uint balAfter = address(c).balance;
            assert(balAfter == balBefore);
        }
        // final general assertion: either call succeeded and returned true, or it reverted; and c's balance unchanged
        // express as a single assert by combining observed facts
        // Note: the earlier asserts already guarantee ok==true when not reverted and balance equality; here we repeat the core general property
        assert(address(c).balance == balBefore);
    }
    receive() external payable { }
}

